  def _def_nodes(self, mod):
    out = []
    def walk(body, themod):
      for s in body:
        if s["t"] == "def":
          append(out, [s, themod])
          walk(s["body"], themod)
        elif s["t"] == "if":
          walk(s["then"], themod)
          for _, eb in s["elifs"]:
            walk(eb, themod)
          walk(s["els"], themod)
        elif s["t"] == "while":
          walk(s["body"], themod)
        elif s["t"] == "for":
          walk(s["body"], themod)
        elif s["t"] == "try":
          walk(s["body"], themod)
          if pyrt.py_get(s, "ebody", null) != null:
            walk(s["ebody"], themod)
          if pyrt.py_get(s, "fbody", null) != null:
            walk(s["fbody"], themod)
        elif s["t"] == "unsafe":
          walk(s["body"], themod)
    walk(mod["prog"], mod)
    for m in self.modules:
      if pyrt.py_get(m, "collected", null):
        walk(m["prog"], m)
    return out
