def build_x64(prog_path, out_path):
  pyrt.py_noop()
  try:
    f = pyrt.py_open(prog_path, null)
    src = f.read_()
    pyrt.py_close(f)
  except as e:
    pyrt.py_print(["error: cannot read " + str(prog_path) + ": " + str(e.strerror or e)])
    return 1
  try:
    prog = normalize.parse(src)
  except as e:
    pyrt.py_print([str(e)])
    return 1
  try:
    irm = irbuild.build_module(prog, "")
    verify.verify_module(irm)
  except as e:
    pyrt.py_print([str(e)])
    return 1
  g = GenIR(irm, pyrt.py_os_path_dirname(pyrt.py_os_path_abspath(prog_path)))
  try:
    img = g.build_ir_image()
  except as e:
    pyrt.py_print([str(e)])
    return 1
  f = pyrt.py_open(out_path, "wb")
  f.write_(img)
  pyrt.py_close(f)
  pyrt.py_os_chmod(out_path, 493)
  pyrt.py_print(["ok: x64 -> " + str(out_path) + " (" + str(len(img)) + " bytes, no gcc)"])
  return 0
def build_x64_ast(prog_path, out_path):
  pyrt.py_noop()
  try:
    f = pyrt.py_open(prog_path, null)
    src = f.read_()
    pyrt.py_close(f)
  except as e:
    pyrt.py_print(["error: cannot read " + str(prog_path) + ": " + str(e.strerror or e)])
    return 1
  try:
    prog = normalize.parse(src)
  except as e:
    pyrt.py_print([str(e)])
    return 1
  g = Gen(prog, prog_path)
  mod = {"name": "<main>", "prog": prog, "pfx": "", "scope": Gen_Scope(null, false), "dir": pyrt.py_os_path_dirname(pyrt.py_os_path_abspath(prog_path))}
  try:
    img = g.build_image(mod)
  except as e:
    pyrt.py_print([str(e)])
    return 1
  f = pyrt.py_open(out_path, "wb")
  f.write_(img)
  pyrt.py_close(f)
  pyrt.py_os_chmod(out_path, 493)
  pyrt.py_print(["ok: x64 -> " + str(out_path) + " (" + str(len(img)) + " bytes, no gcc)"])
  return 0
